from pathlib import Path

DASH=Path('js/modules/dashboard.js')
CSS=Path('css/design-system.css')
TEST=Path('tests/dashboard-card-routes-smoke.test.js')
SW=Path('service-worker.js')

dash=DASH.read_text(encoding='utf-8')
start=dash.find('function dutyRows(list){')
end=dash.find('\nfunction absencesSection',start)
if start<0 or end<0: raise SystemExit('duty block boundaries not found')
new="""function dutyRowHtml(x,{showBook=false,showMine=false}={}){const p=dutyPlace(x)||'Nöbet yeri',mine=!!teacherId()&&x.ogretmenId===teacherId();return `<div class=\"kh-row${showMine&&mine?' is-me':''}\"><div class=\"kh-row-main\"><b>${esc(teacherLabel(x))}</b><small>${dutyPlaceHtml(p)}</small></div>${mine?'<span class=\"kh-chip green\">SİZ</span>':x.defterDolduruldu?'<span class=\"kh-chip green\">TAMAM</span>':'<span class=\"kh-chip\">BUGÜN</span>'}</div>${showBook&&mine?`<label class=\"kh-duty-check\"><input type=\"checkbox\" data-dash-duty-book=\"${esc(x.id)}\" ${x.defterDolduruldu?'checked':''}><span>Nöbet defterini doldurdum</span></label>`:''}`}
function dutySection(){if(!cardVisible('duty'))return'';const list=arr('nobetAtamalari').filter(x=>String(x.tarih||'').slice(0,10)===isoToday()),shield='<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z\"/></svg>';if(isAdmin()){const rows=list.length?sortDuties(list).map(x=>dutyRowHtml(x)).join(''):'<div class=\"kh-empty\">Bugün için nöbet kaydı yok.</div>';return `<section class=\"kh-section\" data-home-section=\"duty\"><div class=\"kh-section-head\"><div class=\"kh-section-title\">${shield}<span>Bugünün Nöbetçileri</span></div><button type=\"button\" class=\"kh-more\" data-dash-route=\"management\" data-dash-page=\"duty\" data-dash-title=\"Nöbet Programı\">Tümü ›</button></div><div class=\"kh-card\">${rows}</div></section>`}const tid=teacherId(),mine=list.filter(x=>tid&&x.ogretmenId===tid);if(!mine.length)return'';return `<section class=\"kh-section\" data-home-section=\"duty\"><div class=\"kh-section-head\"><div class=\"kh-section-title\">${shield}<span>Bugünkü Nöbetim</span></div><button type=\"button\" class=\"kh-more\" data-dash-route=\"management\" data-dash-page=\"duty\" data-dash-title=\"Nöbet Programı\">Program ›</button></div><div class=\"kh-card\">${mine.map(x=>dutyRowHtml(x,{showBook:true,showMine:true})).join('')}</div></section>`}"""
dash=dash[:start]+new+dash[end:]
start=dash.find('function allTodayDutySection(){')
end=dash.find('\nfunction adminShell',start)
if start<0 or end<0: raise SystemExit('allTodayDutySection boundaries not found')
newall="""function allTodayDutySection(){if(isAdmin())return'';const list=arr('nobetAtamalari').filter(x=>String(x.tarih||'').slice(0,10)===isoToday());if(!list.length)return'';const shield='<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z\"/></svg>';return `<section class=\"kh-section\" data-home-section=\"today-duty\"><div class=\"kh-section-head\"><div class=\"kh-section-title\">${shield}<span>Bugünün Nöbetçileri</span></div><button type=\"button\" class=\"kh-more\" data-dash-route=\"management\" data-dash-page=\"duty\" data-dash-title=\"Nöbet Programı\">Tümü ›</button></div><div class=\"kh-card\">${sortDuties(list).map(x=>dutyRowHtml(x,{showMine:true})).join('')}</div></section>`}"""
dash=dash[:start]+newall+dash[end:]
DASH.write_text(dash,encoding='utf-8')

css=CSS.read_text(encoding='utf-8')
marker='/* LEGACY DUTY CARDS — REFERENCE PORT */'
block='''\n\n/* LEGACY DUTY CARDS — REFERENCE PORT */\n.ka-home .kh-section[data-home-section="duty"],.ka-home .kh-section[data-home-section="today-duty"]{display:flex;flex-direction:column;gap:8px}\n.ka-home .kh-section[data-home-section="duty"] .kh-section-head,.ka-home .kh-section[data-home-section="today-duty"] .kh-section-head{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:0 2px}\n.ka-home .kh-section[data-home-section="duty"] .kh-section-title,.ka-home .kh-section[data-home-section="today-duty"] .kh-section-title{display:flex;align-items:center;gap:8px;min-width:0;font-size:15.5px;font-weight:900;color:var(--ka-text)}\n.ka-home .kh-section[data-home-section="duty"] .kh-section-title>svg,.ka-home .kh-section[data-home-section="today-duty"] .kh-section-title>svg{width:19px;height:19px;flex:none;color:var(--ka-primary)}\n.ka-home .kh-section[data-home-section="duty"] .kh-more,.ka-home .kh-section[data-home-section="today-duty"] .kh-more{border:0;background:transparent;color:var(--ka-primary);font:inherit;font-size:10.5px;font-weight:850;padding:6px 2px;white-space:nowrap}\n.ka-home .kh-section[data-home-section="duty"] .kh-card,.ka-home .kh-section[data-home-section="today-duty"] .kh-card{overflow:hidden;border:1px solid var(--ka-border);border-radius:20px;background:var(--ka-card-bg);box-shadow:var(--ka-shadow-sm)}\n.ka-home .kh-section[data-home-section="duty"] .kh-row,.ka-home .kh-section[data-home-section="today-duty"] .kh-row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px;align-items:center;padding:11px 12px;border-bottom:1px solid var(--ka-border)}\n.ka-home .kh-section[data-home-section="duty"] .kh-row:last-of-type,.ka-home .kh-section[data-home-section="today-duty"] .kh-row:last-child{border-bottom:0}\n.ka-home .kh-section[data-home-section="duty"] .kh-row.is-me,.ka-home .kh-section[data-home-section="today-duty"] .kh-row.is-me{background:var(--ka-primary-soft)}\n.ka-home .kh-section[data-home-section="duty"] .kh-row-main,.ka-home .kh-section[data-home-section="today-duty"] .kh-row-main{min-width:0}\n.ka-home .kh-section[data-home-section="duty"] .kh-row-main>b,.ka-home .kh-section[data-home-section="today-duty"] .kh-row-main>b{display:block;font-size:12.5px;line-height:1.28;color:var(--ka-text)}\n.ka-home .kh-section[data-home-section="duty"] .kh-row-main>small,.ka-home .kh-section[data-home-section="today-duty"] .kh-row-main>small{display:block;font-size:10.5px;line-height:1.35;color:var(--ka-text-muted);margin-top:3px}\n.ka-home .kh-section[data-home-section="duty"] .kh-chip,.ka-home .kh-section[data-home-section="today-duty"] .kh-chip{display:inline-flex;align-items:center;padding:5px 8px;border-radius:999px;background:var(--ka-primary-soft);color:var(--ka-primary);font-size:9.5px;font-weight:900;white-space:nowrap}\n.ka-home .kh-section[data-home-section="duty"] .kh-chip.green,.ka-home .kh-section[data-home-section="today-duty"] .kh-chip.green{background:var(--ka-success-soft);color:var(--ka-success)}\n.ka-home .kh-duty-check{display:flex;align-items:center;gap:10px;padding:12px;border-top:1px solid var(--ka-border);font-size:11px;font-weight:700;color:var(--ka-text)}\n.ka-home .kh-duty-check input{width:20px;height:20px;accent-color:var(--ka-primary)}\n'''
if marker not in css: css+=block
CSS.write_text(css,encoding='utf-8')

test=TEST.read_text(encoding='utf-8')
test=test.replace("assert(dash.includes(\"section('Bugünkü Nöbetim'\"),'Öğretmenin kendi nöbeti ayrı odak kartı olmalı.');","assert(dash.includes('<span>Bugünkü Nöbetim</span>')&&dash.includes('class=\\\"kh-duty-check\\\"'),'Öğretmenin kendi nöbeti referans kart ve defter işaretleme davranışıyla ayrı odak olmalı.');",1)
test=test.replace("assert(css.includes('TEACHER DASHBOARD REFINEMENT')&&css.includes('.ka-home-duty-focus'),'Öğretmen dashboard görsel sözleşmesi merkezi design-system içinde olmalı.');","assert(css.includes('LEGACY DUTY CARDS — REFERENCE PORT')&&css.includes('.ka-home .kh-duty-check'),'Öğretmen nöbet görsel sözleşmesi legacy geometriyle merkezi design-system içinde olmalı.');",1)
test=test.replace("assert(dash.includes(\"mine?'Siz':'Bugün'\")&&dash.includes('is-me'),'Bugünün Nöbetçileri kartında oturumdaki öğretmen açıkça işaretlenmeli.');","assert(dash.includes(\"mine?'<span class=\\\"kh-chip green\\\">SİZ</span>'\")&&dash.includes('is-me'),'Bugünün Nöbetçileri kartında oturumdaki öğretmen açıkça işaretlenmeli.');",1)
check="""\nassert(dash.includes('function dutyRowHtml')&&dash.includes('data-home-section=\"duty\"')&&dash.includes('data-home-section=\"today-duty\"'),'Günlük nöbet yüzeyleri ortak legacy kh-row sözleşmesini kullanmalı.');\nassert(!dash.includes('ka-home-duty-focus'),'Yeni taklit ka-home-duty-focus renderer içinde kalmamalı.');\nassert(dash.includes('data-dash-duty-book')&&dash.includes('DutyBookService?.toggle?.'),'Nöbet defteri local-first servis davranışı korunmalı.');\nassert(css.includes('LEGACY DUTY CARDS — REFERENCE PORT')&&css.includes('.ka-home .kh-duty-check'),'Nöbet legacy geometrisi merkezi design-system içinde kalmalı.');\n// Checkpoint: legacy daily duty cards port.\n"""
if 'LEGACY DUTY CARDS — REFERENCE PORT' not in test:test+=check
TEST.write_text(test,encoding='utf-8')

sw=SW.read_text(encoding='utf-8').replace("const CACHE_ADI='oy-cache-v724';","const CACHE_ADI='oy-cache-v725';")
SW.write_text(sw,encoding='utf-8')
